449	     * with the owner's last name.
450	     */
451	    private String customerHash(Owner owner) {
452	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
453	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
454	        return sha256Hex(telephone + lastName, 4, true);
