457	    /**
458	     * Compute the leading hex of SHA-256 over the UTF-8 bytes of {@code input}: the first
459	     * {@code bytes} bytes of the digest rendered as {@code 2 * bytes} hex characters, upper-case when
460	     * {@code upperCase} is {@code true}, otherwise lower-case. Shared by the derived identifiers that
461	     * are built from a SHA-256 prefix (e.g. the household id and the customer-code hash), so the
462	     * digest handling and the "SHA-256 not available" error live in one place.
463	     */
464	    private String sha256Hex(String input, int bytes, boolean upperCase) {
465	        byte[] digest;
466	        try {
467	            digest = MessageDigest.getInstance("SHA-256")
468	                .digest(input.getBytes(StandardCharsets.UTF_8));
469	        } catch (NoSuchAlgorithmException e) {
470	            throw new IllegalStateException("SHA-256 is required but not available", e);
471	        }
472	        String format = upperCase ? "%02X" : "%02x";
473	        StringBuilder hex = new StringBuilder(bytes * 2);
474	        for (int i = 0; i < bytes; i++) {
475	            hex.append(String.format(format, digest[i]));
476	        }
477	        return hex.toString();
478	    }
