private Owner findPossibleDuplicate(Owner owner) {
    String key = householdKey(owner);
    if (key == null) {
        return null;
    }
    String telephone = owner.getTelephone();
    return ownerRepository.findAll().stream()
        .filter(existing -> key.equals(householdKey(existing))
